export function createLeaderboard({endpoint,fetcher=fetch,storage}={}){
 const $=id=>document.getElementById(id);
 let playerId,name='',ticket=null,pending=null,posted=false,busy=false,loadId=0;
 try{storage??=window.localStorage;playerId=storage.getItem('fry-and-fly-player');name=storage.getItem('fry-and-fly-name')||''}catch{}
 if(!/^[0-9a-f]{8}-(?:[0-9a-f]{4}-){3}[0-9a-f]{12}$/i.test(playerId||'')){playerId=crypto.randomUUID();try{storage.setItem('fry-and-fly-player',playerId)}catch{}}
 $('nickname').value=name;
 async function api(path,payload){const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),7000);try{const res=await fetcher(endpoint+path,{method:payload?'POST':'GET',headers:payload?{'Content-Type':'application/json'}:{},body:payload?JSON.stringify(payload):undefined,credentials:'omit',cache:'no-store',signal:controller.signal});let data;try{data=await res.json()}catch{throw new Error('The leaderboard is temporarily unavailable. Please try again.')}if(!res.ok)throw new Error(data.error||'Please try again.');return data}finally{clearTimeout(timer)}}
 function message(text,error=false){$('post-status').textContent=text;$('post-status').classList.toggle('error',error)}
 async function refresh(){const id=++loadId;$('board-refresh').disabled=true;$('board-status').textContent='Loading high scores…';try{const data=await api('/api/scores');if(id!==loadId)return;const body=$('board-rows');body.replaceChildren();if(!data.scores.length){const row=document.createElement('tr'),cell=document.createElement('td');cell.colSpan=4;cell.className='board-empty';cell.textContent='No scores yet. Be the first gull on the board.';row.append(cell);body.append(row)}for(const entry of data.scores){const row=document.createElement('tr');if(pending?.entryId===entry.id)row.className='your-entry';for(const value of ['#'+entry.rank,entry.nickname,entry.score,entry.distance+' m']){const cell=document.createElement('td');cell.textContent=String(value);row.append(cell)}body.append(row)}$('board-status').textContent='Top 20 · most fries wins · distance breaks a tie.'}catch{if(id===loadId)$('board-status').textContent='Could not load scores. Tap Refresh to try again.'}finally{if(id===loadId)$('board-refresh').disabled=false}}
 $('board-refresh').onclick=refresh;
 $('post-jump').onclick=()=>{$('scoreboard').scrollIntoView({behavior:'smooth',block:'start'});$('nickname').focus({preventScroll:true})};
 $('post-form').addEventListener('submit',async event=>{event.preventDefault();if(!pending||posted||busy)return;const captured=pending;busy=true;$('post-submit').disabled=true;$('post-submit').textContent='Posting…';message('Checking your run and saving your score…');try{const nickname=$('nickname').value.trim();try{storage.setItem('fry-and-fly-name',nickname)}catch{}const data=await api('/api/scores',{...captured.payload,nickname,playerId});if(pending!==captured)return;posted=true;captured.entryId=data.entry?.id;$('post-submit').textContent='SCORE POSTED ✓';message(data.bestUpdated?`You are #${data.entry.rank} with ${data.entry.score} fries. Nice getaway!`:`Your best of ${data.entry.score} fries is on the board at #${data.entry.rank}.`);await refresh()}catch(error){if(pending!==captured)return;message(error.name==='AbortError'?'The connection timed out. Your run is still here; try posting again.':error.message,true);$('post-submit').disabled=false;$('post-submit').textContent='TRY AGAIN →'}finally{busy=false}});
 function reset(){ticket=null;pending=null;posted=false;$('post-form').hidden=true;$('post-jump').classList.add('hidden');$('post-intro').textContent='Finish a run, then post your score here.';message('');$('post-submit').disabled=false;$('post-submit').textContent='POST YOUR SCORE →'}
 async function prepareRun(){try{ticket=await api('/api/runs',{version:4,playerId});return ticket}catch{ticket=null;return null}}
 function finish(run){refresh();if(!run.collected){$('post-intro').textContent='Collect at least one fry to post a score.';return}if(!ticket){$('post-intro').textContent='This was a practice run because the leaderboard could not connect. Start a new run to post a score.';return}pending={payload:{token:ticket.id,version:4,steps:run.steps,inputs:run.inputs.map(e=>e.slice())}};$('post-intro').textContent=`YOUR RUN · ${run.collected} FRIES · ${run.distance} M`;$('post-form').hidden=false;$('post-jump').classList.remove('hidden');message('Ready to claim your place?')}
 reset();refresh();return{reset,prepareRun,finish};
}
